import{c as t,Q as n,j as o,m as a}from"./chunks/framework.BqPkuuVc.js";const u=JSON.parse('{"title":"Moving an event to another computer","description":"","frontmatter":{},"headers":[],"relativePath":"user/event-setup/moving-an-event.md","filePath":"user/event-setup/moving-an-event.md"}'),s={name:"user/event-setup/moving-an-event.md"};function r(i,e,h,l,d,p){return n(),o("div",null,[...e[0]||(e[0]=[a('<h1 id="moving-an-event-to-another-computer" tabindex="-1">Moving an event to another computer <a class="header-anchor" href="#moving-an-event-to-another-computer" aria-label="Permalink to &quot;Moving an event to another computer&quot;">​</a></h1><p><strong>Audience:</strong> Organisers who set an event up on one laptop and run it on another, and the person receiving it.</p><p>How to hand a set-up event to whoever is running it on the day, or move it to the laptop that will run it, and what to check once it arrives.</p><h2 id="when-you-need-this" tabindex="-1">When you need this <a class="header-anchor" href="#when-you-need-this" aria-label="Permalink to &quot;When you need this&quot;">​</a></h2><p>Setting an event up and running it are often done on different computers:</p><ul><li>an organiser builds the event at home, on their own laptop, and <strong>sends it to the person running timing</strong> on the day;</li><li>you set it up on your everyday laptop and <strong>move it to the laptop that goes to the event</strong>, the one with the SportIdent station, the printer and the meshO Prime;</li><li>the laptop you planned to use has failed and <strong>another one has to take over</strong>.</li></ul><p>The event moves as a <strong>backup</strong>: one <code>.zip</code> file holding the whole event, which you send and then restore on the other computer. It carries the classes, courses, controls, competitors, start times, screens, map, notes and audit trail exactly as they are.</p><p>Some things don&#39;t move with it, because they belong to the <strong>laptop</strong>, not the event. After a restore, a few things on the new copy need checking, above all its links to the outside world: liveresultat, the cloud and Eventor. Most of this page is that checklist.</p><blockquote><p><strong>Tip:</strong> Move the event <strong>before you click Start event</strong>. A move between days of setup is routine. Moving an event that is already live is possible but is a recovery, not a handover; see <a href="#if-the-event-is-already-live">If the event is already live</a>.</p></blockquote><h2 id="on-the-laptop-the-event-is-leaving" tabindex="-1">On the laptop the event is leaving <a class="header-anchor" href="#on-the-laptop-the-event-is-leaving" aria-label="Permalink to &quot;On the laptop the event is leaving&quot;">​</a></h2><ol><li><strong>Finish setting it up first.</strong> Anything you change on this laptop after taking the backup stays here and won&#39;t be in the copy. If you need to make another change later, make it on the new laptop instead, or take a new backup and send that instead.</li><li>Open the <strong>Events</strong> list. On the event&#39;s card, click <strong>Backup event</strong> (the downward arrow) and choose <strong>Download</strong>. The zip lands in your browser&#39;s downloads folder, with a name like <code>2026-03-14.01__Autumn_Sprint__20260312T081500Z.zip</code>.</li><li>Send the zip to the other person, or copy it to the other laptop: a USB stick, a shared drive, a file-transfer link, email if it&#39;s small enough.</li></ol><blockquote><p><strong>Warning:</strong> Treat the file as private. It holds every competitor&#39;s details, including private ones such as birth year, and it holds the event&#39;s <strong>liveresultat upload password</strong>, which also opens the competition&#39;s organiser page on liveresultat. Don&#39;t post it anywhere public.</p></blockquote><p>Then decide what happens to this laptop&#39;s copy:</p><ul><li><strong>Don&#39;t start it here.</strong> Two copies of one event on two laptops, both started, would both try to publish to the same liveresultat competition (see <a href="#liveresultat">Liveresultat</a>).</li><li><strong>Delete it, or rename it</strong> to something like &quot;Autumn Sprint (old setup copy)&quot; so nobody opens the wrong one later. Deleting is safe once the other laptop has restored the event and checked it.</li></ul><h2 id="on-the-laptop-running-the-event" tabindex="-1">On the laptop running the event <a class="header-anchor" href="#on-the-laptop-running-the-event" aria-label="Permalink to &quot;On the laptop running the event&quot;">​</a></h2><h3 id="restore-it" tabindex="-1">Restore it <a class="header-anchor" href="#restore-it" aria-label="Permalink to &quot;Restore it&quot;">​</a></h3><ol><li>Check that the meshO Manager on this laptop is <strong>the same version or newer</strong> than the one that made the backup. A backup from a newer version is refused, so update this laptop first if you need to.</li><li>Open the <strong>Events</strong> list and click <strong>Restore</strong>. On a laptop with no events yet, it&#39;s <strong>Restore from backup</strong>, under <strong>New event</strong>.</li><li>On the <strong>Local file</strong> tab, click the button and choose the zip.</li><li>Check the <strong>Event name</strong> (see below), then click <strong>Restore</strong>.</li></ol><p>The event opens. It keeps its date, and gets the next free number on that date on this laptop, so its id may not match the original&#39;s. See <a href="./../reference/backup-and-restore#restoring-an-event">Restoring an event</a> for more on what a restore does.</p><h3 id="check-the-name" tabindex="-1">Check the name <a class="header-anchor" href="#check-the-name" aria-label="Permalink to &quot;Check the name&quot;">​</a></h3><p>Restoring asks what to call the event before it&#39;s made. A backup made on <strong>another</strong> computer is offered under its own name, which is what you want for a handover: the name shows on screens, printed splits, exports and liveresultat.</p><p>Manager only adds <strong>(restored)</strong> when the backup came from <strong>this</strong> computer, where the original may be sitting beside the copy. It also adds it for a backup from an older version of Manager that doesn&#39;t record where it was made. Remove it in the name box before clicking <strong>Restore</strong>. If you&#39;ve already restored it, remove it under <strong>Event details → Details → Event name</strong>.</p><h3 id="check-what-came-with-the-event" tabindex="-1">Check what came with the event <a class="header-anchor" href="#check-what-came-with-the-event" aria-label="Permalink to &quot;Check what came with the event&quot;">​</a></h3><p>Work through the <strong>Event details</strong> tabs:</p><table tabindex="0"><thead><tr><th>Tab</th><th>What to check</th></tr></thead><tbody><tr><td><strong>Details</strong></td><td>The name (above) and the date. The date can&#39;t be changed once the event is live, so check it now.</td></tr><tr><td><strong>Live results</strong></td><td>Whether it should publish to liveresultat from here. See <a href="#liveresultat">Liveresultat</a>.</td></tr><tr><td><strong>Cloud sync</strong></td><td>The restored event isn&#39;t linked to any cloud copy the setup laptop published. See <a href="#cloud-sync">Cloud sync</a>.</td></tr><tr><td><strong>Printing</strong></td><td>Any per-event printer choice, such as a <strong>Label printer</strong>, names a printer on the <em>setup</em> laptop. Choose this laptop&#39;s printer, or go back to the global setting.</td></tr><tr><td><strong>Backup &amp; export</strong></td><td>Auto backup and external drive backup. See <a href="#backups">Backups</a>.</td></tr><tr><td><strong>Extensions</strong></td><td>Extensions the event uses must be installed on this laptop too. Their per-event settings came with the event.</td></tr></tbody></table><h4 id="liveresultat" tabindex="-1">Liveresultat <a class="header-anchor" href="#liveresultat" aria-label="Permalink to &quot;Liveresultat&quot;">​</a></h4><p>The event&#39;s link to its liveresultat competition, and the upload password with it, <strong>travels with the event</strong>. That&#39;s deliberate: publishing keeps working after a move without retyping anything. It also means two laptops now hold the same link.</p><ul><li><strong>On this laptop:</strong> open <strong>Live results</strong> and check the competition is the one you expect, and that publishing is switched on if you want it.</li><li><strong>On the setup laptop:</strong> an event only publishes while it&#39;s live, so the old copy is harmless as long as nobody starts it. If somebody might, delete it, or open its <strong>Live results</strong> tab and click <strong>Unlink</strong>. Unlinking only detaches that copy and forgets its password. It changes nothing on liveresultat, and your new laptop keeps publishing. Do it only after the new laptop shows the competition correctly, because the old copy can&#39;t be linked again without the password.</li></ul><h4 id="cloud-sync" tabindex="-1">Cloud sync <a class="header-anchor" href="#cloud-sync" aria-label="Permalink to &quot;Cloud sync&quot;">​</a></h4><p>A restored event is <strong>never</strong> linked to the original&#39;s cloud copy, so it can&#39;t overwrite it. If the setup laptop already published the event to the cloud, this laptop will publish it as a <strong>separate</strong> cloud event when you push it or, if automatic sync is on, when you finish it. Usually the setup laptop hasn&#39;t published anything yet, and there&#39;s nothing to do.</p><h4 id="backups" tabindex="-1">Backups <a class="header-anchor" href="#backups" aria-label="Permalink to &quot;Backups&quot;">​</a></h4><p>The event&#39;s own backup settings travel with it, but check them, because this is the laptop they now have to protect:</p><ul><li><strong>Auto backup</strong>: if it&#39;s off, turn it on. It only runs while the event is live.</li><li><strong>External drive backup</strong>: if the setup laptop had a drive chosen, that drive isn&#39;t plugged into <em>this</em> laptop. Plug in this laptop&#39;s stick, choose it in the <strong>Drive</strong> list and save. Left as it is, the backup raises a &quot;not plugged in&quot; alert once the event starts.</li></ul><p>See <a href="./../reference/backup-and-restore">Backup and restore</a>.</p><h3 id="set-up-what-belongs-to-the-laptop" tabindex="-1">Set up what belongs to the laptop <a class="header-anchor" href="#set-up-what-belongs-to-the-laptop" aria-label="Permalink to &quot;Set up what belongs to the laptop&quot;">​</a></h3><p>These are kept in <strong>Settings</strong> on each laptop and are shared by all its events, so they don&#39;t come with the event. Set them up on the new laptop, or check they already are:</p><table tabindex="0"><thead><tr><th>Setting</th><th>Why it matters</th></tr></thead><tbody><tr><td><strong>Printers</strong> (Settings → Printing)</td><td>Splits and labels print to this laptop&#39;s printers. Each computer&#39;s routes are set up here too.</td></tr><tr><td><strong>Hire cards</strong> (Settings → Hire card registry)</td><td>The pool of the club&#39;s hire cards. Competitors already marked as on a hire card keep that, but a hire card read on the day is only recognised if it&#39;s in this laptop&#39;s pool.</td></tr><tr><td><strong>Hire items</strong> (Settings → Other hire registry)</td><td>The compasses, map boards and so on that the desk lends.</td></tr><tr><td><strong>Custom fields</strong></td><td>Values entered against competitors came with the event, but they only show once a field of the <strong>same name</strong> is defined here.</td></tr><tr><td><strong>Club registry</strong> and <strong>Competitor registry</strong></td><td>Names, clubs and cards Manager suggests as you type. The event&#39;s own competitors and clubs came with it.</td></tr><tr><td><strong>Eventor</strong></td><td>The event still knows its Eventor event. To import late entries or upload results, Eventor must be connected on this laptop with your organisation&#39;s API key.</td></tr><tr><td><strong>Extensions</strong></td><td>Installed per laptop.</td></tr><tr><td><strong>Access protection</strong></td><td>The PIN for opening Manager. Set one if this laptop will be on a shared network.</td></tr><tr><td><strong>Auto backup</strong></td><td>Defaults for <em>new</em> events only. The restored event has its own settings (above).</td></tr></tbody></table><h3 id="things-whose-address-changes" tabindex="-1">Things whose address changes <a class="header-anchor" href="#things-whose-address-changes" aria-label="Permalink to &quot;Things whose address changes&quot;">​</a></h3><p>Every link to the event names the <strong>server it&#39;s on</strong>, and the screens&#39; links also carry the event id. Anything you set up against the setup laptop now points at the wrong place:</p><ul><li><strong>TV screens and info displays.</strong> Open each one again from this laptop&#39;s <strong>Screens</strong> page (see <a href="./../screens/tv-screens">TV screens</a>).</li><li><strong>Access links and QR codes</strong> for download laptops, phones and the entry desk. Take them from this laptop&#39;s <strong>Settings → Server</strong> (see <a href="./../reference/server-addresses">Reaching the server</a>).</li><li><strong>Splits QR codes</strong> set to &quot;Use this server&#39;s spectator URL&quot; on the setup laptop. Set them again in <strong>Event details → Printing</strong>.</li><li><strong>Live export.</strong> Files are written to the <code>Exports</code> folder in this laptop&#39;s data folder. Point whatever reads them (such as EmmaClient) there.</li></ul><h3 id="if-it-s-part-of-a-multi-stage-event" tabindex="-1">If it&#39;s part of a multi-stage event <a class="header-anchor" href="#if-it-s-part-of-a-multi-stage-event" aria-label="Permalink to &quot;If it&#39;s part of a multi-stage event&quot;">​</a></h3><p>A carnival or knock-out competition doesn&#39;t travel as one: each day is its own event, and the multi-stage event that ties them together is kept on the laptop where it was made. A restored day arrives on its own, <strong>not</strong> as a stage.</p><p>To move a whole carnival, back up and restore each day&#39;s event, then on the new laptop create the multi-stage event again and attach each restored event with <strong>Use existing event</strong> on its <strong>Stages</strong> tab. See <a href="./multi-stage-events">Multi-stage events</a>.</p><h2 id="final-check-before-the-day" tabindex="-1">Final check before the day <a class="header-anchor" href="#final-check-before-the-day" aria-label="Permalink to &quot;Final check before the day&quot;">​</a></h2><p>Before you leave the setup laptop behind:</p><ul><li>[ ] The event opens on the new laptop, with its competitors, classes and courses.</li><li>[ ] The event has the name it runs under, with no <strong>(restored)</strong>.</li><li>[ ] Liveresultat is right on this laptop, and the old copy won&#39;t publish.</li><li>[ ] Auto backup is on, and the external drive (if any) is this laptop&#39;s.</li><li>[ ] Printers, hire cards and custom fields are set up here.</li><li>[ ] Screens, access links and QR codes have been taken from this laptop.</li><li>[ ] Card download works: read a test card at the download station.</li><li>[ ] The old copy on the setup laptop is deleted or clearly renamed.</li></ul><h2 id="if-the-event-is-already-live" tabindex="-1">If the event is already live <a class="header-anchor" href="#if-the-event-is-already-live" aria-label="Permalink to &quot;If the event is already live&quot;">​</a></h2><p>If the laptop running a live event has to be replaced mid-event, take the newest auto backup or external drive backup and restore it on the replacement as above. It arrives as <strong>interrupted</strong>; click <strong>Resume event</strong> on its dashboard to carry on. Changes made after that backup was taken aren&#39;t in it. The card-download files and the SportIdent stations&#39; own memory can recover the missing downloads; see <a href="./../reference/backup-and-restore#repairing-a-damaged-event">Repairing a damaged event</a>.</p><p>If you would rather not lose anything, set up a <a href="./../running-the-event/live-standby">live standby</a> before the event: a second computer that keeps a copy updated with every change, and takes over with one button.</p><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="./../reference/backup-and-restore">Backup and restore</a></li><li><a href="./create-event">Creating an event</a> — the Event details tabs</li><li><a href="./../reference/multi-operator-setup">Multi-operator setup</a> — running one event from several computers at once, instead of moving it</li><li><a href="./../reference/server-addresses">Reaching the server: name or IP</a></li><li><a href="./pre-event-checklist">Pre-event checklist</a></li></ul>',50)])])}const g=t(s,[["render",r]]);export{u as __pageData,g as default};
